-- Evaluacion anual de desempeno: metas, competencias, doble evaluacion y planes de mejora.
create table if not exists public.hr_performance_cycles(
 id uuid primary key default gen_random_uuid(),cycle_year integer not null unique check(cycle_year between 2020 and 2100),name text not null,
 start_date date not null,end_date date not null,status text not null default 'PLANIFICACION' check(status in('PLANIFICACION','EVALUACION','CERRADO')),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date)
);
create table if not exists public.hr_performance_evaluations(
 id uuid primary key default gen_random_uuid(),cycle_id uuid not null references public.hr_performance_cycles(id),employee_id uuid not null references public.hr_employees(id),
 supervisor_id uuid references public.hr_employees(id),status text not null default 'PLANIFICADA' check(status in('PLANIFICADA','AUTOEVALUADA','EVALUADA','VALIDADA','CERRADA')),
 self_score numeric(5,2) check(self_score between 0 and 100),supervisor_score numeric(5,2) check(supervisor_score between 0 and 100),goal_score numeric(5,2) check(goal_score between 0 and 100),competency_score numeric(5,2) check(competency_score between 0 and 100),final_score numeric(5,2) check(final_score between 0 and 100),
 employee_comments text not null default '',supervisor_comments text not null default '',final_rating text not null default '',recommend_training boolean not null default false,recommend_promotion boolean not null default false,recommend_compensation boolean not null default false,
 evaluated_by uuid references public.app_users(id),validated_by uuid references public.app_users(id),evaluated_at timestamptz,validated_at timestamptz,
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(cycle_id,employee_id)
);
create table if not exists public.hr_performance_goals(
 id uuid primary key default gen_random_uuid(),evaluation_id uuid not null references public.hr_performance_evaluations(id) on delete cascade,scope text not null check(scope in('INDIVIDUAL','UNIDAD')),description text not null,weight numeric(5,2) not null default 0 check(weight between 0 and 100),target_value text not null default '',result_value text not null default '',score numeric(5,2) check(score between 0 and 100),created_at timestamptz not null default now()
);
create table if not exists public.hr_performance_competencies(
 id uuid primary key default gen_random_uuid(),evaluation_id uuid not null references public.hr_performance_evaluations(id) on delete cascade,competency_name text not null,description text not null default '',weight numeric(5,2) not null default 0 check(weight between 0 and 100),self_score numeric(5,2) check(self_score between 0 and 100),supervisor_score numeric(5,2) check(supervisor_score between 0 and 100),created_at timestamptz not null default now()
);
create table if not exists public.hr_improvement_plans(
 id uuid primary key default gen_random_uuid(),evaluation_id uuid not null unique references public.hr_performance_evaluations(id) on delete cascade,objective text not null,actions text not null,resources text not null default '',responsible text not null,target_date date not null,status text not null default 'ABIERTO' check(status in('ABIERTO','EN_PROGRESO','COMPLETADO','CANCELADO')),progress integer not null default 0 check(progress between 0 and 100),follow_up_notes text not null default '',created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists hr_performance_employee_idx on public.hr_performance_evaluations(employee_id,created_at desc);
alter table public.hr_performance_cycles enable row level security;alter table public.hr_performance_evaluations enable row level security;alter table public.hr_performance_goals enable row level security;alter table public.hr_performance_competencies enable row level security;alter table public.hr_improvement_plans enable row level security;
revoke all on public.hr_performance_cycles,public.hr_performance_evaluations,public.hr_performance_goals,public.hr_performance_competencies,public.hr_improvement_plans from anon,authenticated;

create or replace function public.hr_recalculate_performance(p_evaluation_id uuid) returns void language plpgsql security definer set search_path=public,extensions as $$declare g numeric;c numeric;s numeric;sup numeric;f numeric;begin
 select coalesce(sum(coalesce(score,0)*weight)/nullif(sum(weight),0),0) into g from public.hr_performance_goals where evaluation_id=p_evaluation_id;
 select coalesce(sum(((coalesce(self_score,0)+coalesce(supervisor_score,0))/2)*weight)/nullif(sum(weight),0),0) into c from public.hr_performance_competencies where evaluation_id=p_evaluation_id;
 select coalesce(self_score,0),coalesce(supervisor_score,0) into s,sup from public.hr_performance_evaluations where id=p_evaluation_id;
 f:=round(g*.40+c*.30+s*.10+sup*.20,2);update public.hr_performance_evaluations set goal_score=round(g,2),competency_score=round(c,2),final_score=f,final_rating=case when f>=90 then 'EXCELENTE' when f>=80 then 'MUY_BUENO' when f>=70 then 'BUENO' when f>=60 then 'REQUIERE_MEJORA' else 'INSATISFACTORIO' end,updated_at=now() where id=p_evaluation_id;end $$;

create or replace function public.list_hr_performance(p_token text,p_year integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar desempeño.');end if;
 return jsonb_build_object('success',true,
 'cycles',coalesce((select jsonb_agg(to_jsonb(c) order by cycle_year desc) from public.hr_performance_cycles c),'[]'::jsonb),
 'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'employee_code',e.employee_code,'full_name',e.full_name,'position_name',e.position_name,'direction_name',e.direction_name,'department_name',e.department_name) order by e.full_name) from public.hr_employees e where e.employment_status<>'Desvinculado' and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e))),'[]'::jsonb),
 'evaluations',coalesce((select jsonb_agg(to_jsonb(x) order by x.full_name) from(select ev.*,e.employee_code,e.full_name,e.position_name,e.direction_name,e.department_name,s.full_name supervisor_name,coalesce((select jsonb_agg(to_jsonb(g) order by g.scope,g.created_at) from public.hr_performance_goals g where g.evaluation_id=ev.id),'[]'::jsonb) goals,coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at) from public.hr_performance_competencies c where c.evaluation_id=ev.id),'[]'::jsonb) competencies,(select to_jsonb(p) from public.hr_improvement_plans p where p.evaluation_id=ev.id) improvement_plan from public.hr_performance_evaluations ev join public.hr_performance_cycles cy on cy.id=ev.cycle_id join public.hr_employees e on e.id=ev.employee_id left join public.hr_employees s on s.id=ev.supervisor_id where cy.cycle_year=p_year and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)))x),'[]'::jsonb));end $$;

create or replace function public.manage_hr_performance(p_token text,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_eval public.hr_performance_evaluations;v_cycle uuid;v_id uuid;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para gestionar desempeño.');end if;
 if p_action='CICLO' then insert into public.hr_performance_cycles(cycle_year,name,start_date,end_date,created_by) values((p_data->>'year')::integer,trim(p_data->>'name'),(p_data->>'start_date')::date,(p_data->>'end_date')::date,v_user.id) on conflict(cycle_year) do update set name=excluded.name,start_date=excluded.start_date,end_date=excluded.end_date,updated_at=now() returning id into v_id;
 elsif p_action='EVALUACION' then select id into v_cycle from public.hr_performance_cycles where cycle_year=(p_data->>'year')::integer;if v_cycle is null then return jsonb_build_object('success',false,'error','Primero debe crear el ciclo anual.');end if;insert into public.hr_performance_evaluations(cycle_id,employee_id,supervisor_id,created_by) values(v_cycle,(p_data->>'employee_id')::uuid,nullif(p_data->>'supervisor_id','')::uuid,v_user.id) on conflict(cycle_id,employee_id) do update set supervisor_id=excluded.supervisor_id,updated_at=now() returning id into v_id;
 elsif p_action='META' then select * into v_eval from public.hr_performance_evaluations where id=(p_data->>'evaluation_id')::uuid;if v_eval.id is null then return jsonb_build_object('success',false,'error','Evaluación no encontrada.');end if;insert into public.hr_performance_goals(evaluation_id,scope,description,weight,target_value,result_value,score) values(v_eval.id,upper(p_data->>'scope'),trim(p_data->>'description'),(p_data->>'weight')::numeric,trim(coalesce(p_data->>'target_value','')),trim(coalesce(p_data->>'result_value','')),nullif(p_data->>'score','')::numeric) returning id into v_id;perform public.hr_recalculate_performance(v_eval.id);
 elsif p_action='COMPETENCIA' then select * into v_eval from public.hr_performance_evaluations where id=(p_data->>'evaluation_id')::uuid;if v_eval.id is null then return jsonb_build_object('success',false,'error','Evaluación no encontrada.');end if;insert into public.hr_performance_competencies(evaluation_id,competency_name,description,weight,self_score,supervisor_score) values(v_eval.id,trim(p_data->>'competency_name'),trim(coalesce(p_data->>'description','')),(p_data->>'weight')::numeric,nullif(p_data->>'self_score','')::numeric,nullif(p_data->>'supervisor_score','')::numeric) returning id into v_id;perform public.hr_recalculate_performance(v_eval.id);
 elsif p_action='AUTOEVALUAR' then update public.hr_performance_evaluations set self_score=(p_data->>'score')::numeric,employee_comments=trim(coalesce(p_data->>'comments','')),status='AUTOEVALUADA',updated_at=now() where id=(p_data->>'evaluation_id')::uuid returning * into v_eval;perform public.hr_recalculate_performance(v_eval.id);v_id:=v_eval.id;
 elsif p_action='SUPERVISOR' then update public.hr_performance_evaluations set supervisor_score=(p_data->>'score')::numeric,supervisor_comments=trim(coalesce(p_data->>'comments','')),status='EVALUADA',evaluated_by=v_user.id,evaluated_at=now(),recommend_training=coalesce((p_data->>'recommend_training')::boolean,false),recommend_promotion=coalesce((p_data->>'recommend_promotion')::boolean,false),recommend_compensation=coalesce((p_data->>'recommend_compensation')::boolean,false),updated_at=now() where id=(p_data->>'evaluation_id')::uuid returning * into v_eval;perform public.hr_recalculate_performance(v_eval.id);v_id:=v_eval.id;
 elsif p_action='VALIDAR' then if v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'aprobar_recursos_humanos')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para validar evaluaciones.');end if;update public.hr_performance_evaluations set status='VALIDADA',validated_by=v_user.id,validated_at=now(),updated_at=now() where id=(p_data->>'evaluation_id')::uuid and supervisor_score is not null and self_score is not null returning id into v_id;if v_id is null then return jsonb_build_object('success',false,'error','Faltan la autoevaluación o la evaluación del supervisor.');end if;
 elsif p_action='PLAN_MEJORA' then insert into public.hr_improvement_plans(evaluation_id,objective,actions,resources,responsible,target_date,status,progress,follow_up_notes,created_by) values((p_data->>'evaluation_id')::uuid,trim(p_data->>'objective'),trim(p_data->>'actions'),trim(coalesce(p_data->>'resources','')),trim(p_data->>'responsible'),(p_data->>'target_date')::date,coalesce(nullif(p_data->>'status',''),'ABIERTO'),coalesce((p_data->>'progress')::integer,0),trim(coalesce(p_data->>'follow_up_notes','')),v_user.id) on conflict(evaluation_id) do update set objective=excluded.objective,actions=excluded.actions,resources=excluded.resources,responsible=excluded.responsible,target_date=excluded.target_date,status=excluded.status,progress=excluded.progress,follow_up_notes=excluded.follow_up_notes,updated_at=now() returning id into v_id;
 else return jsonb_build_object('success',false,'error','Acción de desempeño inválida.');end if;insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'DESEMPENO_'||p_action,'Recursos Humanos',p_data||jsonb_build_object('result_id',v_id));return jsonb_build_object('success',true,'id',v_id);end $$;
grant execute on function public.list_hr_performance(text,integer),public.manage_hr_performance(text,text,jsonb) to anon,authenticated;
